using System;
using UnityEngine;

namespace HS2SmartAutoH
{
    // Panel icons: 96x96 alpha masks (white shape, tinted when drawn), base64, bottom row first.
    // Drawn for this mod: goal icons and the reset arrow. FFM / MMF are the game's own icons.
    public static class TCIcons
    {
        public const int Size = 96;

        private const string OffData = "";
        private const string FavourData = "";
        private const string EnjoymentData = "";
        private const string SlaveryData = "";
        private const string AversionData = "";
        private const string BrokenData = "";
        private const string DependenceData = "";
        private const string ResetData = "";

        // Icons of the game's own position menu (two girls + man, girl + two men), in their own colors: RGBA
        private const string FFMData = "";
        private const string MMFData = "";

        // Goal icons in TCGoal order (Free, Favour, Enjoyment, Slavery, Aversion, Broken, Dependence, FFM, MMF)
        public static Texture2D[] Goals;
        public static Texture2D Reset;

        public static void Load()
        {
            if (Goals != null)
            {
                return;
            }
            Goals = new Texture2D[]
            {
                Make(OffData), Make(FavourData), Make(EnjoymentData), Make(SlaveryData),
                Make(AversionData), Make(BrokenData), Make(DependenceData),
                MakeColored(FFMData), MakeColored(MMFData)
            };
            Reset = Make(ResetData);
        }

        // Icons drawn in their own colors (not tinted)
        public static bool IsColored(int goal)
        {
            return goal == 7 || goal == 8;
        }

        private static Texture2D MakeColored(string data)
        {
            byte[] rgba = Convert.FromBase64String(data);
            Color32[] pixels = new Color32[Size * Size];
            for (int i = 0; i < pixels.Length && i * 4 + 3 < rgba.Length; i++)
            {
                pixels[i] = new Color32(rgba[i * 4], rgba[i * 4 + 1], rgba[i * 4 + 2], rgba[i * 4 + 3]);
            }
            return TCPanel.MakeTexture(Size, Size, pixels);
        }

        private static Texture2D Make(string data)
        {
            byte[] alpha = Convert.FromBase64String(data);
            Color32[] pixels = new Color32[Size * Size];
            for (int i = 0; i < pixels.Length && i < alpha.Length; i++)
            {
                pixels[i] = new Color32(255, 255, 255, alpha[i]);
            }
            return TCPanel.MakeTexture(Size, Size, pixels);
        }
    }
}
